function levelOrder(root) {
  if (!root) return []
  const levels = []
  let queue = [root]
  while (queue.length) {
    const next = []
    const level = []
    for (const n of queue) {
      level.push(n.val)
      if (n.left) next.push(n.left)
      if (n.right) next.push(n.right)
    }
    levels.push(level)
    queue = next
  }
  return levels
}
